621   /***********
622    *  WRITE  *
623    ***********/
624   typedef enum logic [1:0] {
625     W_IDLE         ,
626     W_PASSTHROUGH  ,
627     W_INCR_DOWNSIZE,
628     W_SPLIT_INCR_DOWNSIZE
629   } w_state_e;
630 
631   w_state_e w_state_d, w_state_q;
632 
633   // This FIFO holds the number of bursts generated by each write transactions handled by this downsizer.
634   // This is used to forward only the correct B beats to the slave.
635   logic forward_b_beat_i;
636   logic forward_b_beat_o;
637   logic forward_b_beat_push;
638   logic forward_b_beat_pop;
639   logic forward_b_beat_full;
640 
641   fifo_v3 #(
642     .DATA_WIDTH  (1          ),
643     .DEPTH       (AxiMaxReads),
644     .FALL_THROUGH(1'b1       )
645   ) i_forward_b_beats_queue (
646     .clk_i     (clk_i               ),
647     .rst_ni    (rst_ni              ),
648     .flush_i   (1'b0                ),
649     .testmode_i(1'b0                ),
650     .data_i    (forward_b_beat_i    ),
651     .push_i    (forward_b_beat_push ),
652     .full_o    (forward_b_beat_full ),
653     .data_o    (forward_b_beat_o    ),
654     .pop_i     (forward_b_beat_pop  ),
655     .empty_o   (/* Unused */        ),
656     .usage_o   (/* Unused */        )
657   );
658 
659   always_comb begin
660     inject_aw_into_ar_req = 1'b0;
661 
662     // i_num_b_beats default state
663     forward_b_beat_i    = '0  ;
664     forward_b_beat_push = 1'b0;
665     forward_b_beat_pop  = 1'b0;
666 
667     // Maintain state
668     w_state_d = w_state_q;
669     w_req_d   = w_req_q  ;
670 
671     // AW Channel
672     mst_req.aw          = w_req_q.aw      ;
673     mst_req.aw_valid    = w_req_q.aw_valid;
674     slv_resp_o.aw_ready = '0              ;
675 
676     // Throw an error.
677     mst_req_aw_err = w_req_q.aw_throw_error;
678 
679     // W Channel
680     mst_req.w          = '0;
681     mst_req.w_valid    = '0;
682     slv_resp_o.w_ready = '0;
683 
684     // B Channel (No latency)
685     if (mst_resp.b_valid) begin
686       // Merge response of this burst with prior one according to precedence rules.
687       w_req_d.burst_resp = axi_pkg::resp_precedence(w_req_q.burst_resp, mst_resp.b.resp);
688     end
689     slv_resp_o.b      = mst_resp.b        ;
690     slv_resp_o.b.resp = w_req_d.burst_resp;
691 
692     // Each write transaction might trigger several B beats on the master (narrow) side.
693     // Only forward the last B beat of each transaction.
694     if (forward_b_beat_o) begin
695       slv_resp_o.b_valid = mst_resp.b_valid ;
696       mst_req.b_ready    = slv_req_i.b_ready;
697 
698       // Got an ack on the B channel. Pop transaction.
699       if (mst_req.b_ready && mst_resp.b_valid)
700         forward_b_beat_pop = 1'b1;
701     end else begin
702       // Otherwise, just acknowlegde the B beats
703       slv_resp_o.b_valid = 1'b0            ;
704       mst_req.b_ready    = 1'b1            ;
705       forward_b_beat_pop = mst_resp.b_valid;
706     end
707 
708     // Got a grant on the AW channel
709     if (mst_req.aw_valid & mst_resp.aw_ready) begin
710       w_req_d.aw_valid       = 1'b0;
711       w_req_d.aw_throw_error = 1'b0;
712     end
713 
714     case (w_state_q)
715       W_PASSTHROUGH, W_INCR_DOWNSIZE, W_SPLIT_INCR_DOWNSIZE: begin
716         // Request was accepted
717         if (!w_req_q.aw_valid)
718           if (slv_req_i.w_valid) begin
719             automatic addr_t mst_port_offset = AxiMstPortStrbWidth == 1 ? '0 : w_req_q.aw.addr[idx_width(AxiMstPortStrbWidth)-1:0];
720             automatic addr_t slv_port_offset = AxiSlvPortStrbWidth == 1 ? '0 : w_req_q.aw.addr[idx_width(AxiSlvPortStrbWidth)-1:0];
721 
722             automatic mst_data_t w_data = mst_req.w.data;
723 
724             // Valid output
725             mst_req.w_valid = 1'b1               ;
726             mst_req.w.last  = w_req_q.aw.len == 0;
727             mst_req.w.user  = slv_req_i.w.user   ;
728 
729             // Lane steering
730             for (int b = 0; b < AxiSlvPortStrbWidth; b++)
731               if ((b >= slv_port_offset) &&
732                   (b - slv_port_offset < (1 << w_req_q.orig_aw_size)) &&
733                   (b + mst_port_offset - slv_port_offset < AxiMstPortStrbWidth)) begin
734                 w_data[b + mst_port_offset - slv_port_offset]         = slv_req_i.w.data[8*b +: 8];
735                 mst_req.w.strb[b + mst_port_offset - slv_port_offset] = slv_req_i.w.strb[b]       ;
736               end
737             mst_req.w.data = w_data;
738           end
739 
740         // Acknowledgment
741         if (mst_resp.w_ready && mst_req.w_valid) begin
742           w_req_d.burst_len = w_req_q.burst_len - 1;
743           w_req_d.aw.len    = w_req_q.aw.len - 1   ;
744 
745           case (w_req_d.aw.burst)
746             axi_pkg::BURST_INCR: begin
747               w_req_d.aw.addr = aligned_addr(w_req_q.aw.addr, w_req_q.aw.size) + (1 << w_req_q.aw.size);
748             end
749             axi_pkg::BURST_FIXED: begin
750               w_req_d.aw.addr = w_req_q.aw.addr;
751             end
752           endcase
753 
754           case (w_state_q)
755             W_PASSTHROUGH:
756               slv_resp_o.w_ready = 1'b1;
757 
758             W_INCR_DOWNSIZE, W_SPLIT_INCR_DOWNSIZE:
759               if (w_req_q.burst_len == 0 || (aligned_addr(w_req_d.aw.addr, w_req_q.orig_aw_size) != aligned_addr(w_req_q.aw.addr, w_req_q.orig_aw_size)))
760                 slv_resp_o.w_ready = 1'b1;
761           endcase
762 
763           // Trigger another burst request, if needed
764           if (w_state_q == W_SPLIT_INCR_DOWNSIZE)
765             // Finished current burst, but whole transaction hasn't finished
766             if (w_req_q.aw.len == '0 && w_req_q.burst_len != '0 && !forward_b_beat_full) begin
767               w_req_d.aw_valid = 1'b1;
768               w_req_d.aw.len   = (w_req_d.burst_len <= 255) ? w_req_d.burst_len : 255;
769 
770               // We will receive an extraneous B beat. Ignore it.
771               forward_b_beat_i    = 1'b0;
772               forward_b_beat_push = 1'b1;
773             end
774 
775           if (w_req_q.burst_len == 0 && !forward_b_beat_full) begin
776             w_state_d = W_IDLE;
777 
778             forward_b_beat_push = 1'b1;
779             forward_b_beat_i    = 1'b1;
780           end
781         end
782       end
783     endcase
784 
785     // Can start a new request as soon as w_state_d is W_IDLE
786     if (w_state_d == W_IDLE) begin
787       // Reset channels
788       w_req_d.aw             = '0                ;
789       w_req_d.aw_valid       = 1'b0              ;
790       w_req_d.aw_throw_error = 1'b0              ;
791       w_req_d.burst_resp     = axi_pkg::RESP_OKAY;
792 
793       if (!forward_b_beat_full) begin
794         if (slv_req_i.aw_valid && slv_req_i.aw.atop[5]) begin // ATOP with an R response
795           inject_aw_into_ar_req = 1'b1                 ;
796           slv_resp_o.aw_ready   = inject_aw_into_ar_gnt;
797         end else begin // Regular AW
798           slv_resp_o.aw_ready = 1'b1;
799         end
800 
801         // New write request
802         if (slv_req_i.aw_valid && slv_resp_o.aw_ready) begin
803           // Default state
804           w_state_d = W_PASSTHROUGH;
805 
806           // Save beat
807           w_req_d.aw            = slv_req_i.aw      ;
808           w_req_d.aw_valid      = 1'b1              ;
809           w_req_d.burst_len     = slv_req_i.aw.len  ;
810           w_req_d.orig_aw_len   = slv_req_i.aw.len  ;
811           w_req_d.orig_aw_size  = slv_req_i.aw.size ;
812           w_req_d.orig_aw_burst = slv_req_i.aw.burst;
813 
814           case (slv_req_i.aw.burst)
815             axi_pkg::BURST_INCR: begin
816               // Evaluate downsize ratio
817               automatic addr_t size_mask  = (1 << slv_req_i.aw.size) - 1                                              ;
818               automatic addr_t conv_ratio = ((1 << slv_req_i.aw.size) + AxiMstPortStrbWidth - 1) / AxiMstPortStrbWidth;
819 
820               // Evaluate output burst length
821               automatic addr_t align_adj = (slv_req_i.aw.addr & size_mask & ~MstPortByteMask) / AxiMstPortStrbWidth;
822               w_req_d.burst_len          = (slv_req_i.aw.len + 1) * conv_ratio - align_adj - 1                     ;
823 
824               if (conv_ratio != 1) begin
825                 w_req_d.aw.size = AxiMstPortMaxSize;
826 
827                 if (w_req_d.burst_len <= 255) begin
828                   w_state_d      = W_INCR_DOWNSIZE  ;
829                   w_req_d.aw.len = w_req_d.burst_len;
830                 end else begin
831                   w_state_d      = W_SPLIT_INCR_DOWNSIZE;
832                   w_req_d.aw.len = 255 - align_adj      ;
833                 end
834               end
835             end
836 
837             axi_pkg::BURST_FIXED: begin
838               // Single transaction
839               if (slv_req_i.aw.len == '0) begin
840                 // Evaluate downsize ratio
841                 automatic addr_t size_mask  = (1 << slv_req_i.aw.size) - 1                                              ;
842                 automatic addr_t conv_ratio = ((1 << slv_req_i.aw.size) + AxiMstPortStrbWidth - 1) / AxiMstPortStrbWidth;
843 
844                 // Evaluate output burst length
845                 automatic addr_t align_adj = (slv_req_i.aw.addr & size_mask & ~MstPortByteMask) / AxiMstPortStrbWidth;
846                 w_req_d.burst_len          = (conv_ratio >= align_adj + 1) ? (conv_ratio - align_adj - 1) : 0;
847 
848                 if (conv_ratio != 1) begin
849                   w_state_d        = W_INCR_DOWNSIZE    ;
850                   w_req_d.aw.len   = w_req_d.burst_len  ;
851                   w_req_d.aw.size  = AxiMstPortMaxSize  ;
852                   w_req_d.aw.burst = axi_pkg::BURST_INCR;
853                 end
854               end else begin
855                 // The downsizer does not support fixed bursts
856                 w_req_d.aw_throw_error = 1'b1;
857               end
858             end
859 
860             axi_pkg::BURST_WRAP: begin
861               // The DW converter does not support this type of burst.
862               w_state_d              = W_PASSTHROUGH;
863               w_req_d.aw_throw_error = 1'b1         ;
864             end
865           endcase
866         end
867       end
868     end
869   end
870 
871   always_ff @(posedge clk_i or negedge rst_ni) begin
872     if (!rst_ni) begin
873       w_state_q <= W_IDLE;
874       w_req_q   <= '0    ;
875     end else begin
876       w_state_q <= w_state_d;
877       w_req_q   <= w_req_d  ;
878     end
879   end
